// source/blender/blenlib/tests/BLI_math_vector_types_test.cc:466
pub fn math_vec_types__SwizzleComparison()->Report{
let mut r=Report::default();
let mut a:v::V<i32,4> = v::construct::<i32,4>(&[&(1) as &dyn v::Components, &(2) as &dyn v::Components, &(3) as &dyn v::Components, &(4) as &dyn v::Components]);
  let mut b:v::V<i32,3> = v::construct::<i32,3>(&[&(1) as &dyn v::Components, &(2) as &dyn v::Components, &(3) as &dyn v::Components]);

  eq!(r, a.swizzle([0,1,2,3]) == a, true);
  eq!(r, a == a.swizzle([0,1,2,3]), true);
  eq!(r, a.swizzle([3,2,1,0]) == a.swizzle([0,1,2,3]), false);
  eq!(r, a.swizzle([0,1,2,3]) != a, false);
  eq!(r, a != a.swizzle([0,1,2,3]), false);
  eq!(r, a.swizzle([3,2,1,0]) != a.swizzle([0,1,2,3]), true);
  eq!(r, a.swizzle([0,1,2,2]) == b.swizzle([0,1,2,2]), true);
  eq!(r, a.swizzle([0,1,2,2]) != b.swizzle([0,1,2,2]), false);
r
}

